  Hash,
  Inbox,
  Mail,
  Paperclip,
  Search,
} from "lucide-react";
import { SourceUpload } from "./source-upload";

export const dynamic = "force-dynamic";

type SearchParams = Promise<Record<string, string | string[] | undefined>>;

type EmailAttachment = {
  attachment_id?: string;
  filename?: string;
  description?: string;
  content_type?: string;
  document_id?: string;
  document_type?: string;
  original_filename?: string;
  path?: string;
};

type FileSource = {
  sourceType: "file";
  id: string;
  fileName: string;
  objectKey: string;
  contentType: string;
  sizeBytes: number;
  status: string;
  createdAt: Date;
  documentType: string | null;
  relatedVoyageId: string | null;
  relatedVesselName: string | null;
  sourceEmailId: string | null;
  sourceAttachmentId: string | null;
  originalAttachmentFilename: string | null;
  sourceCreatedAt: string | null;
  content: string | null;
};

type EmailSource = {
  sourceType: "email";
  id: string;
  threadId: string;
  subject: string;
  from: string;
  to: string[];
  cc: string[];
  sentAt: string;
  body: string;
  relatedVoyageId: string;
  relatedVesselName: string;
  attachments: EmailAttachment[];
};

type Source = FileSource | EmailSource;

export default async function SourcesPage({ searchParams }: { searchParams: SearchParams }) {
  const params = await searchParams;
  const workspaceId = await ensureDefaultWorkspace();
  const selectedType = getParam(params.type);
  const selectedId = getParam(params.id);
  const selectedChunkId = getParam(params.chunk);
  const query = getParam(params.q)?.trim() ?? "";

  const fileWhere = query
    ? and(
        eq(documents.workspaceId, workspaceId),
        eq(documents.status, "ready"),
        or(
          ilike(documents.fileName, `%${query}%`),
          ilike(maritimeDocuments.relatedVoyageId, `%${query}%`),
          ilike(maritimeDocuments.relatedVesselName, `%${query}%`),
          ilike(maritimeDocuments.documentType, `%${query}%`),
        ),
      )
    : and(eq(documents.workspaceId, workspaceId), eq(documents.status, "ready"));

  const emailWhere = query
    ? and(
        eq(maritimeEmails.workspaceId, workspaceId),
        or(
          ilike(maritimeEmails.subject, `%${query}%`),
          ilike(maritimeEmails.from, `%${query}%`),
          ilike(maritimeEmails.relatedVoyageId, `%${query}%`),
          ilike(maritimeEmails.relatedVesselName, `%${query}%`),
        ),
      )
    : eq(maritimeEmails.workspaceId, workspaceId);

  const [fileRows, emailRows] = await Promise.all([
    db
      .select({
        id: documents.id,
        fileName: documents.fileName,
        objectKey: documents.objectKey,
        contentType: documents.contentType,
        sizeBytes: documents.sizeBytes,
        status: documents.status,
        createdAt: documents.createdAt,
        documentType: maritimeDocuments.documentType,
        relatedVoyageId: maritimeDocuments.relatedVoyageId,
        relatedVesselName: maritimeDocuments.relatedVesselName,
        sourceEmailId: maritimeDocuments.sourceEmailId,
        sourceAttachmentId: maritimeDocuments.sourceAttachmentId,
        originalAttachmentFilename: maritimeDocuments.originalAttachmentFilename,
        sourceCreatedAt: maritimeDocuments.sourceCreatedAt,
        content: maritimeDocuments.content,
      })
      .from(documents)
      .leftJoin(maritimeDocuments, eq(maritimeDocuments.documentId, documents.id))
      .where(fileWhere)
      .orderBy(desc(documents.createdAt), asc(documents.fileName)),
    db
      .select({
        id: maritimeEmails.id,
        threadId: maritimeEmails.threadId,
        subject: maritimeEmails.subject,
        from: maritimeEmails.from,
        to: maritimeEmails.to,
        cc: maritimeEmails.cc,
        sentAt: maritimeEmails.sentAt,
        body: maritimeEmails.body,
        relatedVoyageId: maritimeEmails.relatedVoyageId,
        relatedVesselName: maritimeEmails.relatedVesselName,
        attachments: maritimeEmails.attachments,
      })
      .from(maritimeEmails)
      .where(emailWhere)
      .orderBy(desc(maritimeEmails.sentAt), asc(maritimeEmails.subject)),
  ]);

  const files: FileSource[] = fileRows.map((row) => ({ ...row, sourceType: "file" }));
  const emails: EmailSource[] = emailRows.map((row) => ({
    ...row,
    sourceType: "email",
    attachments: normalizeAttachments(row.attachments),
  }));
  const selectedSource = selectSource(files, emails, selectedType, selectedId);
  const selectedChunks =
    selectedSource?.sourceType === "file"
      ? await db
          .select({
            id: documentChunks.id,
            chunkIndex: documentChunks.chunkIndex,
            content: documentChunks.content,
            tokenEstimate: documentChunks.tokenEstimate,
          })
          .from(documentChunks)
          .where(eq(documentChunks.documentId, selectedSource.id))
          .orderBy(asc(documentChunks.chunkIndex))
      : [];

  return (
    <div className="space-y-5">
      <SourceUpload />

      <section className="grid gap-4 lg:grid-cols-[390px_minmax(0,1fr)]">
        <aside className="overflow-hidden rounded-lg border border-slate-200 bg-white">
          <div className="border-b border-slate-200 p-4">
            <div className="flex items-start justify-between gap-3">
              <div>
                <div className="flex items-center gap-2 text-sm font-semibold text-slate-950">
                  <Database className="h-4 w-4 text-slate-500" />
                  Indexed source library
                </div>
                <p className="mt-1 text-xs leading-5 text-slate-500">
                  {files.length} files and {emails.length} emails
                  {query ? ` matching "${query}"` : ""}
                </p>
              </div>
              <Badge className="border-emerald-200 bg-emerald-50 text-emerald-700" variant="outline">
                Ready
              </Badge>
            </div>

            <form className="mt-4 flex gap-2" action="/workspace/sources">
              <div className="relative min-w-0 flex-1">
                <Search className="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <Input
                  aria-label="Search indexed sources"
                  className="pl-8"
                  defaultValue={query}
                  name="q"
                  placeholder="Search voyage, vessel, sender, file"
                />
              </div>
              <Button size="icon" type="submit" variant="outline">
                <Search className="h-4 w-4" />
              </Button>
            </form>
          </div>

          <div className="max-h-[calc(100vh-250px)] overflow-y-auto">
            <SourceGroup
              currentId={selectedSource?.id}
              currentType={selectedSource?.sourceType}
              query={query}
              sources={files}
              title="Indexed files"
            />
            <SourceGroup
              currentId={selectedSource?.id}
              currentType={selectedSource?.sourceType}
              query={query}
              sources={emails}
              title="Emails"
            />
          </div>
        </aside>

        <div className="min-w-0">
          {selectedSource ? (
            selectedSource.sourceType === "file" ? (
              <FilePreview file={selectedSource} selectedChunkId={selectedChunkId} chunks={selectedChunks} />
            ) : (
              <EmailPreview email={selectedSource} query={query} />
            )
          ) : (
            <EmptyPreview />
          )}
        </div>
      </section>
    </div>
  );
}

function SourceGroup({
  currentId,
  currentType,
  query,
  sources,
  title,
}: {
  currentId?: string;
  currentType?: Source["sourceType"];
  query: string;
  sources: Source[];
  title: string;
}) {
  return (
    <div className="border-b border-slate-200 last:border-b-0">
      <div className="sticky top-0 z-[1] flex items-center justify-between border-b border-slate-100 bg-slate-50 px-4 py-2">
        <div className="text-xs font-semibold uppercase tracking-normal text-slate-500">{title}</div>
        <div className="text-xs text-slate-400">{sources.length}</div>
      </div>
      <div className="divide-y divide-slate-100">
        {sources.length === 0 ? (
          <div className="px-4 py-6 text-sm text-slate-500">No sources found.</div>
        ) : (
          sources.map((source) => (
            <SourceLink
              isSelected={currentType === source.sourceType && currentId === source.id}
              key={`${source.sourceType}-${source.id}`}
              query={query}
              source={source}
            />
          ))
        )}
      </div>
    </div>
  );
}

function SourceLink({
  isSelected,
  query,
  source,
}: {
  isSelected: boolean;
  query: string;
  source: Source;
}) {
  const href = sourceHref(source.sourceType, source.id, query);
  const Icon = source.sourceType === "file" ? FileText : Mail;
  const title = source.sourceType === "file" ? source.fileName : source.subject;
  const eyebrow =
    source.sourceType === "file"
      ? formatSourceType(source.documentType ?? source.contentType)
      : `${source.fromName} ${source.sentAt}`;
