type MarkdownBlock =
  | { type: "heading"; level: number; text: string }
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] }
  | { type: "table"; rows: string[][] };

function parseMarkdownBlocks(source: string): MarkdownBlock[] {
  const blocks: MarkdownBlock[] = [];
  const lines = source.split("\n");
  let index = 0;

  while (index < lines.length) {
    const line = lines[index].trim();

    if (!line) {
      index += 1;
      continue;
    }

    const heading = /^(#{1,4})\s+(.+)$/.exec(line);
    if (heading) {
      blocks.push({ type: "heading", level: heading[1].length, text: heading[2] });
      index += 1;
      continue;
    }

    if (line.startsWith("|")) {
      const rows: string[][] = [];
      while (index < lines.length && lines[index].trim().startsWith("|")) {
        const row = lines[index].trim();
        if (!/^\|\s*-+/.test(row)) {
          rows.push(
            row
              .split("|")
              .slice(1, -1)
              .map((cell) => cell.trim()),
          );
        }
        index += 1;
      }
      blocks.push({ type: "table", rows });
      continue;
    }

    if (line.startsWith("- ")) {
      const items: string[] = [];
      while (index < lines.length && lines[index].trim().startsWith("- ")) {
        items.push(lines[index].trim().slice(2));
        index += 1;
      }
      blocks.push({ type: "list", items });
      continue;
    }

    const paragraph: string[] = [];
    while (index < lines.length && lines[index].trim() && !isMarkdownBoundary(lines[index].trim())) {
      paragraph.push(lines[index].trim());
      index += 1;
    }
    blocks.push({ type: "paragraph", text: paragraph.join(" ") });
  }

  return blocks;
}

function isMarkdownBoundary(line: string) {
  return /^(#{1,4})\s+/.test(line) || line.startsWith("- ") || line.startsWith("|");
}

function selectSource(files: FileSource[], emails: EmailSource[], type?: string, id?: string) {
  if (id) {
    if (type === "email") return emails.find((email) => email.id === id) ?? emails[0] ?? files[0];
    if (type === "file") return files.find((file) => file.id === id) ?? files[0] ?? emails[0];

    return (
      files.find((file) => file.id === id) ??
      emails.find((email) => email.id === id) ??
      files[0] ??
      emails[0]
    );
  }

  if (type === "email") return emails[0] ?? files[0];
  return files[0] ?? emails[0];
}

function sourceHref(type: Source["sourceType"], id: string, query?: string, chunkId?: string) {
  const params = new URLSearchParams({ type, id });
  if (query) params.set("q", query);
  if (chunkId) params.set("chunk", chunkId);
  return `/workspace/sources?${params.toString()}`;
}

function getParam(value: string | string[] | undefined) {
  return Array.isArray(value) ? value[0] : value;
}

function normalizeAttachments(value: Record<string, unknown>[]) {
  return value.map((attachment) => attachment as EmailAttachment);
}

function stripFrontMatter(source: string) {
  return source.replace(/^---\n[\s\S]*?\n---\n?/, "").trim();
}

function formatSourceType(value: string) {
  return value.replace(/[._/-]+/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function formatDate(value: Date | string) {
  return new Intl.DateTimeFormat("en", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(typeof value === "string" ? new Date(value) : value);
}

