+                    <tr className={rowIndex === 0 ? "bg-slate-50" : "bg-white"} key={`${index}-${rowIndex}`}>
+                      {row.map((cell, cellIndex) => (
+                        <td
+                          className={cn(
+                            "px-3 py-2 align-top",
+                            rowIndex === 0 ? "font-semibold text-slate-950" : "text-slate-700",
+                            cellIndex === 0 && rowIndex > 0 && "font-medium text-slate-950",
+                          )}
+                          key={`${index}-${rowIndex}-${cellIndex}`}
+                        >
+                          {cell}
+                        </td>
+                      ))}
