+
+function stripFrontMatter(source: string) {
+  return source.replace(/^---\n[\s\S]*?\n---\n?/, "").trim();
+}
+
+function sourceTitle(source: Source) {
+  return source.sourceType === "file" ? source.fileName : source.subject;
